namespace ghidra.app.plugin.core.overview;



using docking;
using ghidra.util;

/**
 * Convenience dialog for showing a Legend for an {@link OverviewColorComponent}
 */
public class OverviewColorLegendDialog : DialogComponentProvider {

	/**
	 * Constructs a new {@link DialogComponentProvider} to show the given component with a "Dismiss"
	 * button.
	 *
	 * @param title the title of the dialog
	 * @param component the component to show as the main area of the dialog.
	 * @param help the help location for the dialog.
	 */
	public OverviewColorLegendDialog(string title, JComponent component, HelpLocation help) : base(title, false)
    {
		component.getAccessibleContext().setAccessibleName("Overview Color Legend");
		addWorkPanel(component);
		addDismissButton();
		setHelpLocation(help);
		setRememberLocation(true);
		setRememberSize(false);
	}

	public void refresh() {
		getComponent().repaint();
	}

}
